const DB_NAME = 'Kanji';
const DB_VERSION = 1;
const STORE_NAME = 'kanjiStore';

/**
 * Initializes the database. 
 * Creates the schema and indexes if running for the first time.
 * @returns {Promise<IDBDatabase>} The active database instance.
 */
export function init() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    // This handles creation and structural updates
    request.onupgradeneeded = function(event) {
      const db = event.target.result;

      if (!db.objectStoreNames.contains(STORE_NAME)) {
        // 'index' matches the integer ID field in your JSON dataset
        const store = db.createObjectStore(STORE_NAME, { keyPath: 'index' });

        // Setup specialized search pathways
        store.createIndex('kanjiIndex', 'kanji', { unique: true });
        store.createIndex('onyomiIndex', 'onyomi', { unique: false });
        store.createIndex('dueIndex', 'due', { unique: false });
        importData();

        console.log("Database structure initialized successfully.");
      }
    };

    request.onsuccess = function(event) {
      resolve(event.target.result);
    };

    request.onerror = function(event) {
      reject(`Database initialization failed: ${event.target.error}`);
    };
  });
}

/**
 * Fetches every single record stored in the database.
 * @param {IDBDatabase} db - The active database instance.
 * @returns {Promise<Array>} List of all kanji objects.
 */
export function getAll(db) {
  return new Promise((resolve, reject) => {
    init().then(db => {
      const transaction = db.transaction([STORE_NAME], 'readonly');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.getAll();

      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(`Failed to get all records: ${request.error}`);
    });
  });
}

/**
 * Retrieves a single record using its numeric index.
 * @param {IDBDatabase} db - The active database instance.
 * @param {number} indexId - The ID number (e.g., 1, 2, 3).
 * @returns {Promise<Object|null>} The matched kanji object or null.
 */
export function getByIndex(indexId) {
  return new Promise((resolve, reject) => {
    init().then(db => {
      const transaction = db.transaction([STORE_NAME], 'readonly');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.get(indexId);

      request.onsuccess = () => resolve(request.result || null);
      request.onerror = () => reject(`Failed to get record #${indexId}: ${request.error}`);
    });
  });
}

/**
 * Searches for a record using the exact Kanji character string.
 * @param {IDBDatabase} db - The active database instance.
 * @param {string} character - The kanji character (e.g., "一").
 * @returns {Promise<Object|null>} The matched kanji object or null.
 */
export function getByCharacter(character) {
  return new Promise((resolve, reject) => {
    init().then(db => {
      const transaction = db.transaction([STORE_NAME], 'readonly');
      const store = transaction.objectStore(STORE_NAME);
      const index = store.index('kanjiIndex');
      const request = index.get(character);

      request.onsuccess = () => resolve(request.result || null);
      request.onerror = () => reject(`Search failed for ${character}: ${request.error}`);
    });
  });
}

/**
 * Seeds data into the database if you need to add your JSON.
 * @param {IDBDatabase} db - The active database instance.
 * @param {Array<Object>} dataArray - Array of JSON objects matching your structure.
 * @returns {Promise<string>} Success string message.
 */
export function importData(db) {
  return new Promise((resolve, reject) => {
    init().then(db => {
      const transaction = db.transaction([STORE_NAME], 'readwrite');
      const store = transaction.objectStore(STORE_NAME);

      kanjiData.forEach(item => {
        store.put(item); // Overwrites duplicates safely
      });

      transaction.oncomplete = () => resolve("Data import finished successfully.");
      transaction.onerror = () => reject(`Data import aborted: ${transaction.error}`);
    });
  });
}

/**
 * Updates an entire record in the database.
 * If the record's 'index' matches an existing entry, it overwrites it.
 * @param {IDBDatabase} db - The active database instance.
 * @param {Object} updatedRecord - The complete modified object (must include 'index').
 * @returns {Promise<number>} The index ID of the updated record.
 */
export function update(updatedRecord) {
  return new Promise((resolve, reject) => {
    // 1. Open a transaction with 'readwrite' permissions
    init().then(db => {
      const transaction = db.transaction(['kanjiStore'], 'readwrite');
      const store = transaction.objectStore('kanjiStore');

      // 2. Use .put() to replace the old object with the new one
      const request = store.put(updatedRecord);

      request.onsuccess = () => {
        resolve(request.result); // Returns the primary key of the record
      };

      request.onerror = () => {
        reject(`Failed to update record: ${request.error}`);
      };
    });
  });
} 

/**
 * Retrieves all cards due today or earlier.
 * @param {IDBDatabase} db
 * @param {Temporal.PlainDate} temporalDate - Usually Temporal.Now.plainDateISO()
 */
export function getDue() {
  return new Promise((resolve, reject) => {
    init().then(db => {
      const today = Temporal.Now.plainDateISO().toString();
      const transaction = db.transaction([STORE_NAME], 'readonly');
      const store = transaction.objectStore(STORE_NAME);
      const index = store.index('dueIndex');
      // Create an IDBKeyRange that bounds the upper limit to our target date string
      const range = IDBKeyRange.upperBound(today);
      const request = index.getAll(range);

      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(`Query failed: ${request.error}`);
    });
  });
}

/**
 * Retrieves all cards where the 'due' field is explicitly set to null.
 * @param {IDBDatabase} db - The active database instance.
 * @returns {Promise<Array>} List of un-scheduled kanji objects.
 */
export function getNew() {
  return new Promise((resolve, reject) => {
    init().then(db => {
      const transaction = db.transaction([STORE_NAME], 'readonly');
      const store = transaction.objectStore(STORE_NAME);
      const results = [];

      // Open a cursor to walk through every record in the store
      const request = store.openCursor();

      request.onsuccess = function(event) {
        const cursor = event.target.result;

        if (cursor) {
          const record = cursor.value;

          // Check if the due field is null (or missing entirely)
          if (!record.due) {
            results.push(record);
          }

          // Move to the next record in the database
          cursor.continue();
        } else {
          // The cursor is finished; return the final filtered array
          resolve(results);
        }
      };

      request.onerror = () => reject(`Cursor filtering failed: ${request.error}`);
    });
  });
}
